/* ============ الأستاذ · الشركة · المهني · النادي · نبض السوق ============ */

/* ---------- واجهة التقييم المشتركة (أستاذ + مهني) ---------- */
const EV = {};
const RLEVELS = ['بداية', 'نامٍ', 'متمكّن', 'متميّز'];
const SNIPPETS = ['فكرة قوية ومبنية على بحث واضح.', 'شدّ التسلسل في النصوص الثانوية.', 'تباين الألوان لا ينجح في تطبيقين.', 'اعرض شبكة بناء الشعار.', 'جاهز لنقطة التحقق التالية.'];
function evalTotal(q) { const e = EV[q.id]; return Math.round(q.rubric.reduce((a, [n, w]) => a + (e.s[n] ? w * e.s[n] / 4 : 0), 0)); }
const artwork = () => `<div class="grid grid-cols-3 gap-2">
  <div class="well aspect-square grid place-items-center" data-tip="نظام الشعار.pdf · الشعار الأساسي"><svg viewBox="0 0 100 100" class="w-3/5" aria-hidden="true"><g fill="none" stroke="var(--gold)" stroke-width="3" stroke-linecap="round"><path d="M50 88V40"/>${[0, 1, 2, 3, 4].map(i => `<path d="M50 ${44 - i * 6}C${36 - i * 4} ${36 - i * 7} ${26 - i * 3} ${40 - i * 4} ${16 + i * 2} ${50 - i * 6}"/><path d="M50 ${44 - i * 6}C${64 + i * 4} ${36 - i * 7} ${74 + i * 3} ${40 - i * 4} ${84 - i * 2} ${50 - i * 6}"/>`).join('')}</g><circle cx="50" cy="50" r="46" fill="none" stroke="var(--line-2)"/></svg></div>
  <div class="well aspect-square p-3 flex flex-col justify-between" data-tip="مواصفات اللون والخط.pdf"><div class="grid grid-cols-4 gap-1">${['#2B2118', '#E2B866', '#7A8F6B', '#F3EBDD'].map(c => `<span class="aspect-square rounded" style="background:${c}"></span>`).join('')}</div><div><p class="display text-xl font-bold leading-tight">أبجد</p><p class="text-[10px] text-muted mt-1">خط العرض · لمسة كوفية</p></div></div>
  <div class="well aspect-square grid place-items-center" data-tip="التطبيقات.png · كوب، قائمة، لافتة"><div class="w-1/2 aspect-[3/4] rounded-b-[30%] rounded-t-md bg-[#F3EBDD] grid place-items-center"><span class="logo-ar text-[#2B2118] text-lg">نخلة</span></div></div></div>`;
function evalView(roleKey, arg) {
  const q = S.queue.find(x => x.id === arg) || S.queue[0];
  const isPro = roleKey === 'professional', base = isPro ? 'reviews' : 'evaluate';
  if (!q) return `${head(isPro ? 'مراجعة المشاريع' : 'قائمة التقييم', 'لا شيء بانتظارك.', `أُرسل ${S.done.length} تقييمات في هذه الجلسة.`)}${empty('inbox', 'القائمة فارغة', 'تظهر التسليمات الجديدة هنا فور إرسالها.')}`;
  const list = `<div class="grid gap-2">${S.queue.map(x => `<a href="#${roleKey}-${base}-${x.id}" class="well p-3 flex gap-3 items-start hover:border-[var(--line-2)] transition ${x.id === q.id ? 'border-[var(--gold)]' : ''}">${av(x.who, 'av-sm')}<span class="min-w-0 flex-1"><span class="block text-sm leading-snug">${x.title}</span><span class="block text-xs text-muted mt-1">${P(x.who).n} · ${x.due}</span></span>${x.pr === 'high' ? `<span class="dot mt-2" style="--c:var(--crit)" data-tip="أولوية عالية"></span>` : ''}</a>`).join('')}</div>`;
  EV[q.id] = EV[q.id] || { s: q.id === 'q1' ? { 'الفكرة والبحث': 4, 'الخطوط': 3 } : {}, fb: '' };
  const e = EV[q.id];
  return `${head(isPro ? 'مراجعة المشاريع · تقييم مهني' : 'قائمة التقييم', isPro ? 'راجعي العمل كما يراجعه الاستوديو.' : 'قيّم العمل، لا الطالب.', `${S.queue.length} تسليمات بانتظارك. الدرجة تحدّث جواز مهارات الطالب لحظة الإرسال.`)}
  <div class="grid xl:grid-cols-12 gap-3">
    <aside class="xl:col-span-3 card card-pad content-start" data-rv>${sectionTitle('بالانتظار', `<span class="chip num">${S.queue.length}</span>`)}${list}</aside>
    <section class="xl:col-span-5 card card-pad" data-rv>
      <div class="flex items-center gap-3">${av(q.who)}<div class="min-w-0 flex-1"><p class="font-semibold">${P(q.who).n}</p><p class="text-xs text-muted">${P(q.who).major} · ${P(q.who).yr}</p></div><span class="chip">${q.kind}</span></div>
      <h2 class="display text-2xl font-bold mt-5 leading-snug">${q.title}</h2>
      <div class="mt-3 flex flex-wrap gap-2"><span class="chip">${I('sparkles')}${q.skill}</span><span class="chip">${I('clock')}${q.due}</span></div>
      <div class="well p-4 mt-5"><p class="text-xs text-muted mb-1.5">ملاحظة الطالب</p><p class="text-sm leading-relaxed">«${q.note}»</p></div>
      <p class="eyebrow mt-6 mb-3">الأدلة المرفقة</p>
      ${q.id === 'q1' ? artwork() : ''}
      <div class="grid gap-2 mt-2">${q.files.map(([f, sz]) => `<div class="well px-3 py-2.5 flex items-center gap-3 text-sm"><span class="text-muted">${I(f.endsWith('.png') ? 'image' : 'file-text', 'w-4 h-4')}</span><span class="flex-1 truncate">${f}</span><span class="text-xs text-muted num" dir="ltr">${sz}</span><button class="btn btn-ghost btn-sm" data-act="openFile">${I('eye')}فتح</button></div>`).join('')}${q.link ? `<div class="well px-3 py-2.5 flex items-center gap-3 text-sm"><span class="text-muted">${I('link-2', 'w-4 h-4')}</span><span class="flex-1">${q.link}</span></div>` : ''}</div>
    </section>
    <section class="xl:col-span-4 card card-pad" data-rv data-eval="${q.id}">
      ${sectionTitle('معايير التقييم', `<span class="text-xs text-muted">مجموع الأوزان 100</span>`)}
      <div class="grid gap-4">${q.rubric.map(([n, w]) => `<div data-crit="${esc(n)}"><div class="flex justify-between text-sm mb-2"><span>${n}</span><span class="text-muted num">${w}%</span></div><div class="grid grid-cols-4 gap-1">${RLEVELS.map((l, i) => `<button class="h-9 rounded-lg text-[12px] border hair transition ${e.s[n] === i + 1 ? 'bg-[var(--gold)] text-[#17130B] border-transparent font-semibold' : 'bg-[var(--bg-2)] text-ink2 hover:text-ink'}" data-act="rub" data-q="${q.id}" data-n="${esc(n)}" data-v="${i + 1}" aria-pressed="${e.s[n] === i + 1}">${l}</button>`).join('')}</div></div>`).join('')}</div>
      <div class="well p-4 mt-5 flex items-center justify-between"><div><p class="text-xs text-muted">الدرجة الموزونة</p><p class="display text-4xl font-bold num leading-none mt-1"><span id="evTotal">${evalTotal(q)}</span><span class="text-base text-ink2">/100</span></p></div><div class="text-xs text-muted" id="evState">قُيّم ${Object.keys(e.s).length} من ${q.rubric.length}</div></div>
      <div class="field mt-5"><label class="label" for="evFb">تغذية راجعة مكتوبة</label><textarea class="textarea" id="evFb" placeholder="ما الذي نجح، وما الذي يحتاج إصلاحًا، وما الخطوة التالية">${esc(e.fb)}</textarea></div>
      <div class="flex flex-wrap gap-1.5 mt-2">${SNIPPETS.map(s => `<button class="chip" data-act="snip">${s}</button>`).join('')}</div>
      <div class="mt-5 grid grid-cols-2 gap-2"><button class="btn" data-act="evReturn" data-q="${q.id}" data-r="${roleKey}">${I('undo-2')}إعادة للتعديل</button><button class="btn btn-primary" data-act="evSubmit" data-q="${q.id}" data-r="${roleKey}">${I('check')}إرسال التقييم</button></div>
      <p class="text-xs text-muted mt-3">الإرسال يسجّل ${isPro ? 'تقييمًا مهنيًا' : 'تقييم أستاذ'} باسمك مع المعايير والتاريخ.</p>
    </section>
  </div>`;
}
ACT.rub = el => {
  const q = S.queue.find(x => x.id === el.dataset.q), e = EV[q.id], n = el.dataset.n;
  e.s[n] = +el.dataset.v;
  $$(`[data-crit="${CSS.escape(n)}"] button`).forEach(b => { const on = +b.dataset.v === e.s[n]; b.className = `h-9 rounded-lg text-[12px] border hair transition ${on ? 'bg-[var(--gold)] text-[#17130B] border-transparent font-semibold' : 'bg-[var(--bg-2)] text-ink2 hover:text-ink'}`; b.setAttribute('aria-pressed', on); });
  const t = $('#evTotal'), v = evalTotal(q);
  if (window.gsap && !RM) { const o = { v: +t.textContent }; gsap.to(o, { v, duration: .4, ease: 'power2.out', onUpdate: () => t.textContent = Math.round(o.v) }); } else t.textContent = v;
  $('#evState').textContent = `قُيّم ${Object.keys(e.s).length} من ${q.rubric.length}`;
  SFX.play('toggle');
};
ACT.snip = el => { const t = $('#evFb'); t.value = (t.value ? t.value.trim() + ' ' : '') + el.textContent; t.dispatchEvent(new Event('input', { bubbles: true })); };
document.addEventListener('input', e => { if (e.target.id === 'evFb') { const q = e.target.closest('[data-eval]'); if (q && EV[q.dataset.eval]) EV[q.dataset.eval].fb = e.target.value; } });
ACT.openFile = () => toast('معاينة الملفات متاحة في المنتج الكامل. التجربة تعرض المصغّرات أعلاه.', 'eye');
function finishEval(el, returned) {
  const q = S.queue.find(x => x.id === el.dataset.q), e = EV[q.id], role = el.dataset.r;
  if (!returned && Object.keys(e.s).length < q.rubric.length) { toast(`قيّم المعايير الـ ${q.rubric.length} كلها قبل الإرسال.`, 'alert-circle'); return; }
  if (!e.fb.trim()) { $('#evFb').focus(); toast('أضف تغذية راجعة مكتوبة ليعرف الطالب خطوته التالية.', 'alert-circle'); return; }
  const score = evalTotal(q), who = ROLES[role].who;
  S.queue = S.queue.filter(x => x.id !== q.id); S.done.push({ ...q, score, returned, by: who });
  if (q.sid === 'gd' && !returned) {
    const s = skill('gd'); s.evaluator = who; s.st = s.st === 'verified' ? 'verified' : 'evaluated';
    s.ev.unshift({ t: role === 'professional' ? 'professional' : 'professor', title: `تقييم نقطة التحقق 2: ${score}/100. ${e.fb.slice(0, 80)}`, src: P(who).n, d: '2026-11-14' });
    s.missing = s.missing || 'مصدر دليل مستقل ثانٍ، ودرجة 70 فأكثر في الاختبار النهائي.';
  }
  SFX.play('success');
  toast(returned ? `أُعيد العمل إلى <b>${P(q.who).n}</b> مع الملاحظات.` : `أُرسل التقييم: <b>${score}/100</b>. تحدّث جواز ${P(q.who).n.split(' ')[0]}.`, returned ? 'undo-2' : 'badge-check');
  buildShell();
  const base = role === 'professional' ? 'reviews' : 'evaluate', next = S.queue[0];
  location.hash = next ? `#${role}-${base}-${next.id}` : `#${role}-${base}`;
}
ACT.evSubmit = el => finishEval(el, false);
ACT.evReturn = el => finishEval(el, true);

/* ---------- الأستاذ ---------- */
VIEWS.professor.overview = () => `${head('د. فيصل القحطاني · التفاعل بين الإنسان والحاسب', 'حيث تلتقي النظرية بالموجز.', 'طلابك ومساراتهم، والأعمال التي تنتظر مراجعتك.', `<a class="btn" href="#professor-content">${I('pen-line')}انشر شرحًا</a><a class="btn btn-primary" href="#professor-evaluate">${I('clipboard-check')}راجع ${S.queue.length} تسليمات</a>`)}
  <div class="grid grid-cols-2 lg:grid-cols-4 gap-3">${stat('طلاب تحت الإشراف', 46, { icon: 'users', go: 'professor-students' })}${stat('بانتظار المراجعة', S.queue.length, { icon: 'inbox', sub: 'واحد يُسلَّم اليوم', go: 'professor-evaluate' })}${stat('بحاجة لمساعدة', 4, { icon: 'life-buoy', sub: 'رُصدوا بقواعد النشاط', go: 'professor-students' })}${stat('تقييمات مكتملة', 128 + S.done.length, { icon: 'badge-check', sub: 'هذا العام الأكاديمي' })}</div>
  <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 mt-3">${stat('مسارات تعلم نشطة', 6, { icon: 'route', go: 'professor-paths' })}${stat('تحديات ومهام منشأة', 9, { icon: 'list-checks', go: 'professor-tasks' })}${stat('ساعات الإرشاد', 14, { icon: 'messages-square', sub: 'نوفمبر' })}${stat('شروحات منشورة', 12, { icon: 'library', go: 'professor-content' })}</div>
  <div class="grid lg:grid-cols-12 gap-3 mt-3">
    <div class="card card-pad lg:col-span-7" data-rv>${sectionTitle('تحليلات تقدم الطلاب', `<span class="text-xs text-muted">متوسط درجات نقاط التحقق</span>`)}<div class="pt-5">${chart('line', { labels: TREND_MONTHS, series: [{ name: 'طلابي', vals: [54, 57, 60, 61, 64, 67, 69, 71], color: 'var(--gold)' }, { name: 'متوسط القسم', vals: TREND_COHORT, color: 'var(--text-2)', dash: true }], h: 210, min: 40, max: 80 })}</div></div>
    <div class="card card-pad lg:col-span-5" data-rv>${sectionTitle('طلاب بحاجة لمساعدة')}<div class="grid gap-2">${[['khalid', 'بلا نشاط منذ 3 أسابيع', 'crit'], ['abdullah', 'فاتته نقطة التحقق مرتين', 'crit'], ['lama', 'موعد لوحة الطاقة مهدد', 'warn'], ['yousef', 'تراجعت درجته 12 نقطة', 'warn']].map(([w, t, c]) => `<div class="well p-3 flex items-center gap-3">${av(w, 'av-sm')}<div class="min-w-0 flex-1"><p class="text-sm">${P(w).n}</p><p class="text-xs text-muted">${t}</p></div><span class="chip sem sem-${c}">${I(c === 'crit' ? 'alert-octagon' : 'alert-triangle')}${c === 'crit' ? 'معرّض للتعثر' : 'تحت المتابعة'}</span><button class="btn btn-ghost btn-sm" data-act="nudge" data-id="${w}">تواصل</button></div>`).join('')}</div></div>
  </div>
  <div class="grid lg:grid-cols-2 gap-3 mt-3">
    <div class="card card-pad" data-rv>${sectionTitle('التقييمات أسبوعيًا')}${chart('bars', { labels: ACTIVITY_WEEKS, vals: [5, 7, 6, 9, 11, 8, 12, 10, 9, 13, 11, 7], unit: 'تقييمات', tipPrefix: 'الأسبوع ', h: 180 })}</div>
    <div class="card card-pad" data-rv>${sectionTitle('التالي في القائمة', `<a class="text-xs text-ink2 hover:text-ink" href="#professor-evaluate">فتح القائمة</a>`)}<div class="grid gap-2">${S.queue.slice(0, 4).map(q => `<a href="#professor-evaluate-${q.id}" class="well p-3 flex items-center gap-3 hover:border-[var(--line-2)] transition">${av(q.who, 'av-sm')}<span class="flex-1 min-w-0"><span class="block text-sm truncate">${q.title}</span><span class="block text-xs text-muted">${q.skill} · ${q.due}</span></span>${I('chevron-right', 'w-4 h-4 text-muted')}</a>`).join('') || empty('inbox', 'لا شيء بالانتظار', 'أنهيت كل المراجعات.')}</div></div>
  </div>`;
ACT.nudge = el => { SFX.play('success'); toast(`أُرسلت متابعة إلى <b>${P(el.dataset.id).n}</b> مع خطوة تالية مقترحة.`, 'send'); };
VIEWS.professor.evaluate = arg => evalView('professor', arg);
VIEWS.professor.students = () => {
  const rows = [['reem', 'التصميم الجرافيكي', S.pathDone ? 100 : 38, 'اليوم', 'good'], ['khalid', 'أبحاث المستخدم', 22, 'قبل 3 أسابيع', 'crit'], ['lama', 'تحليل البيانات', 61, 'أمس', 'warn'], ['hessa', 'إتاحة الوصول', 74, 'قبل يومين', 'good'], ['yousef', 'أساسيات الحوسبة السحابية', 35, 'قبل 4 أيام', 'warn'], ['omar', 'الخلفيات البرمجية ببايثون', 88, 'اليوم', 'good'], ['noura', 'التفكير بالمنتج', 57, 'أمس', 'good'], ['abdullah', 'الهوية البصرية', 29, 'قبل 9 أيام', 'crit']];
  const L = { good: 'على المسار', warn: 'تحت المتابعة', crit: 'معرّض للتعثر' };
  return `${head('الطلاب تحت الإشراف', '46 طالبًا في 6 مسارات.', 'الحالة محسوبة من النشاط ودرجات نقاط التحقق والمواعيد.')}
  <div class="card" data-rv><div class="scroll-x"><table class="tbl min-w-[780px]"><thead><tr><th>الطالب</th><th>المسار</th><th>التقدم</th><th>آخر نشاط</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(([w, p, pr, la, st]) => `<tr><td><div class="flex items-center gap-3">${av(w, 'av-sm')}<div><p class="font-semibold">${P(w).n}</p><p class="text-xs text-muted">${P(w).major}</p></div></div></td><td class="text-ink2">${p}</td><td><div class="flex items-center gap-2 min-w-[140px]"><span class="num w-9 text-sm">${pr}%</span><div class="flex-1">${bar(pr, 'thin')}</div></div></td><td class="text-ink2 text-sm">${la}</td><td><span class="chip sem sem-${st}">${L[st]}</span></td><td class="text-end"><button class="btn btn-ghost btn-sm" data-act="nudge" data-id="${w}">${I('send')}رسالة</button></td></tr>`).join('')}</tbody></table></div></div>`;
};
VIEWS.professor.paths = () => `${head('مسارات التعلم', 'المسارات التي تشرف عليها.', 'أنت مسؤول عن الأسس الأكاديمية، والمهنيون والشركات يضيفون طبقة السوق.')}
  <div class="grid md:grid-cols-2 xl:grid-cols-3 gap-3">${[['التصميم الجرافيكي', 12, 41, 3, 'pen-tool'], ['أبحاث المستخدم', 9, 52, 2, 'search'], ['أساسيات تحليل البيانات', 14, 47, 4, 'bar-chart-3'], ['تصميم الواجهات الاحترافي', 6, 78, 0, 'layout'], ['ممارسات إتاحة الوصول', 3, 66, 1, 'accessibility'], ['أساسيات إدارة المشاريع', 8, 70, 1, 'kanban']].map(([n, s, p, c, ic]) => `<div class="card card-pad" data-rv><div class="flex justify-between items-center"><span class="role-ico">${I(ic)}</span>${c ? `<span class="chip sem sem-warn">${c} نقاط تحقق للمراجعة</span>` : `<span class="chip sem sem-good">محدّث</span>`}</div><p class="mt-4 font-semibold">${n}</p><p class="text-xs text-muted mt-1">${s} طالبًا مسجّلًا</p><div class="mt-4 flex justify-between text-xs mb-1.5"><span class="text-muted">متوسط التقدم</span><span class="num">${p}%</span></div>${bar(p, 'thin')}<div class="mt-5 flex gap-2"><a class="btn btn-sm" href="#student-paths">عرض كطالب</a><a class="btn btn-sm btn-ghost" href="#professor-evaluate">نقاط التحقق</a></div></div>`).join('')}</div>`;
