ACT.star = el => { const w = el.dataset.id; S.shortlist.has(w) ? S.shortlist.delete(w) : S.shortlist.add(w); SFX.play('toggle'); toast(S.shortlist.has(w) ? `أُضيف <b>${P(w).n}</b> للقائمة المختصرة` : 'أُزيل من القائمة المختصرة', 'star'); buildShell(); rerender(); };
