const WZ = { step: 0, title: 'تصميم ميزة هدف ادخار للطلاب', desc: 'يريد الطلاب الادخار لشيء واحد في كل مرة. صمّم التدفق من تحديد الهدف حتى أول تحويل تلقائي.', cat: 'التصميم', skill: 'تصميم واجهات المستخدم', lvl: 'متوسط', deliverables: ['نموذج Figma', 'مخطط تدفق المستخدم', 'مبرر مختصر'], dur: 10, rubric: [['وضوح التدفق', 30], ['الجودة البصرية', 25], ['إتاحة الوصول', 20], ['المبرر', 25]], reqs: { pdf: true, link: true, video: false, team: false } };
const WZ_STEPS = ['الأساسيات', 'المهارة', 'المخرجات', 'المعايير', 'التسليم', 'المراجعة'];
const LVL_HINT = { 'مبتدئ': 'يتبع موجزًا موجّهًا', 'متوسط': 'يعمل باستقلالية', 'متقدم': 'يوازن الخيارات ويشرحها', 'خبير': 'يضع التوجه للآخرين' };
ACT.wzGo = el => { const d = +el.dataset.d; if (d > 0 && WZ.step === 3 && WZ.rubric.reduce((a, r) => a + r[1], 0) !== 100) { toast('مجموع أوزان المعايير يجب أن يساوي 100.', 'alert-circle'); return; } WZ.step = Math.max(0, Math.min(5, WZ.step + d)); rerender(); };
