ACT.wzAddDel = () => { const v = $('#wzDel').value.trim(); if (!v) return; WZ.deliverables.push(v); rerender(); };
ACT.wzRmDel = el => { WZ.deliverables.splice(+el.dataset.i, 1); rerender(); };
ACT.wzAddCrit = () => { WZ.rubric.push(['معيار جديد', 0]); rerender(); };
