ACT.wzPublish = () => {
  const reqMap = { pdf: 'ملفات PDF أو PNG', link: 'رابط نموذج أو مستودع', video: 'فيديو شرح مدته 3 دقائق', team: 'فرق حتى 3 أعضاء (كل عضو يحدد دوره)' };
  S.challenges.unshift({ id: 'c' + Date.now(), co: CO, title: WZ.title, desc: WZ.desc, skill: WZ.skill, cat: WZ.cat, lvl: WZ.lvl, dur: WZ.dur + ' أيام', apps: 0, subs: 0, st: 'open', isNew: true, deliverables: WZ.deliverables.slice(), rubric: WZ.rubric.map(r => [...r]), reqs: Object.keys(WZ.reqs).filter(k => WZ.reqs[k]).map(k => reqMap[k]) });
  WZ.step = 0; SFX.play('success'); toast(`نُشر <b>${esc(WZ.title)}</b>. يراه الطلاب الآن في التحديات العملية.`, 'rocket'); location.hash = '#company-challenges';
};
