     <div class="field"><span class="label">مستوى الإتقان المطلوب</span><div class="seg">${LEVELS.map(l => `<button type="button" class="${l === WZ.lvl ? 'on' : ''}" data-act="wzLvl">${l}</button>`).join('')}</div></div>
